logic [7:0] timer;
always_ff @(posedge clk or negedge rst_n)
  if (!rst_n)             timer <= 8'h0;
  else if (state == WAIT) timer <= timer + 1;
  else                    timer <= 8'h0;
assign timeout = (timer > 8'd200);
always_comb begin
  next_state = state;
  case (state)
    WAIT: if (ack || timeout) next_state = IDLE;
  endcase
end
